    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_64(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_list_scuttle_exit_progress(
    List<ScuttleExitProgress>? self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_list_scuttle_exit_progress(self, serializer);
    }
  }

  @protected
  void sse_encode_scuttle_board_anchor(
    ScuttleBoardAnchor self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.height, serializer);
    sse_encode_String(self.hash, serializer);
  }

  @protected
  void sse_encode_scuttle_board_funding(
    ScuttleBoardFunding self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.address, serializer);
    sse_encode_u_32(self.expiryHeight, serializer);
    sse_encode_String(self.token, serializer);
  }

  @protected
  void sse_encode_scuttle_board_result(
    ScuttleBoardResult self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.fundingTxid, serializer);
    sse_encode_u_32(self.movementId, serializer);
    sse_encode_u_64(self.amountSats, serializer);
    sse_encode_list_String(self.vtxoIds, serializer);
  }

  @protected
  void sse_encode_scuttle_board_terms(
    ScuttleBoardTerms self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.serverKey, serializer);
    sse_encode_u_32(self.tipHeight, serializer);
    sse_encode_String(self.tipHash, serializer);
    sse_encode_u_32(self.requiredConfirmations, serializer);
    sse_encode_u_64(self.grossSats, serializer);
    sse_encode_u_64(self.feeSats, serializer);
    sse_encode_u_64(self.netSats, serializer);
  }

  @protected
  void sse_encode_scuttle_exit(ScuttleExit self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.vtxoId, serializer);
    sse_encode_u_64(self.amountSats, serializer);
    sse_encode_scuttle_exit_state(self.state, serializer);
    sse_encode_u_32(self.tipHeight, serializer);
    sse_encode_opt_box_autoadd_u_32(self.claimableHeight, serializer);
    sse_encode_opt_String(self.claimTxid, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_claim(
    ScuttleExitClaim self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_prim_u_8_strict(self.signedPsbt, serializer);
    sse_encode_list_prim_u_8_strict(self.rawTransaction, serializer);
    sse_encode_String(self.txid, serializer);
    sse_encode_u_64(self.feeSats, serializer);
    sse_encode_list_scuttle_exit_claim_input(self.inputs, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_claim_input(
    ScuttleExitClaimInput self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.vtxoId, serializer);
    sse_encode_u_64(self.amountSats, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_cpfp_candidate(
    ScuttleExitCpfpCandidate self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.exitTxid, serializer);
    sse_encode_String(self.childTxid, serializer);
    sse_encode_list_prim_u_8_strict(self.rawTransaction, serializer);
    sse_encode_u_64(self.feeSats, serializer);
    sse_encode_list_String(self.reserveInputs, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_cpfp_step(
    ScuttleExitCpfpStep self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.vtxoId, serializer);
    sse_encode_String(self.parentTxid, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_fee_estimate(
    ScuttleExitFeeEstimate self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.exitBroadcastFeeSats, serializer);
    sse_encode_u_64(self.claimFeeSats, serializer);
    sse_encode_u_64(self.totalFeeSats, serializer);
    sse_encode_u_64(self.broadcastRateSatPerKwu, serializer);
    sse_encode_u_64(self.transactionsToBroadcast, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_progress(
    ScuttleExitProgress self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_scuttle_exit(self.exit, serializer);
    sse_encode_bool(self.failed, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_progress_review(
    ScuttleExitProgressReview self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.accountId, serializer);
    sse_encode_u_64(self.feeRateSatPerVb, serializer);
    sse_encode_list_scuttle_exit(self.activeExits, serializer);
    sse_encode_list_scuttle_reserve_coin(self.confirmedCoins, serializer);
  }

  @protected
  void sse_encode_scuttle_exit_state(
    ScuttleExitState self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_scuttle_mixed_claim(
    ScuttleMixedClaim self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_prim_u_8_strict(self.signedPsbt, serializer);
    sse_encode_list_prim_u_8_strict(self.rawTransaction, serializer);
    sse_encode_String(self.txid, serializer);
    sse_encode_u_64(self.feeSats, serializer);
    sse_encode_list_scuttle_exit_claim_input(self.inputs, serializer);
  }

  @protected
  void sse_encode_scuttle_mixed_claim_review(
    ScuttleMixedClaimReview self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_scuttle_reserve_coin(self.reserve, serializer);
    sse_encode_u_64(self.amountSats, serializer);
    sse_encode_u_64(self.feeSats, serializer);
  }

  @protected
  void sse_encode_scuttle_network(
    ScuttleNetwork self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_scuttle_observation(
    ScuttleObservation self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.tipHeight, serializer);
    sse_encode_u_64(self.lastKnownSpendableSats, serializer);
    sse_encode_list_scuttle_vtxo(self.vtxos, serializer);
  }

  @protected
  void sse_encode_scuttle_recovery_status(
    ScuttleRecoveryStatus self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_scuttle_reserve_coin(
    ScuttleReserveCoin self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.outpoint, serializer);
    sse_encode_u_64(self.amountSats, serializer);
    sse_encode_u_32(self.confirmationHeight, serializer);
  }

  @protected
  void sse_encode_scuttle_vtxo(ScuttleVtxo self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_u_64(self.amountSats, serializer);
    sse_encode_u_32(self.expiryHeight, serializer);
    sse_encode_scuttle_vtxo_state(self.state, serializer);
  }

  @protected
  void sse_encode_scuttle_vtxo_state(
    ScuttleVtxoState self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

@sealed
class ScuttleWalletImpl extends RustOpaque implements ScuttleWallet {
  // Not to be used by end users
  ScuttleWalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  ScuttleWalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        ScuttleCore.instance.api.rust_arc_increment_strong_count_ScuttleWallet,
    rustArcDecrementStrongCount:
        ScuttleCore.instance.api.rust_arc_decrement_strong_count_ScuttleWallet,
    rustArcDecrementStrongCountPtr: ScuttleCore
        .instance
        .api
        .rust_arc_decrement_strong_count_ScuttleWalletPtr,
  );

  /// Checks the server identity, fee schedule and chain tip without initiating a board.
  Future<ScuttleBoardTerms> boardTerms({
    required BigInt amountSats,
    ScuttleBoardAnchor? anchor,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletBoardTerms(
    that: this,
    amountSats: amountSats,
    anchor: anchor,
  );

  /// Waits for an admitted operation to finish before dropping the wallet.
  Future<void> close() =>
      ScuttleCore.instance.api.crateApiWalletScuttleWalletClose(that: this);

  /// Verifies the locally known confirmed reserve outputs without syncing or broadcasting.
  Future<List<ScuttleReserveCoin>> confirmedReserve() => ScuttleCore
      .instance
      .api
      .crateApiWalletScuttleWalletConfirmedReserve(that: this);

  /// Delivers only the exact child previously admitted by the host. A
  /// response error is not proof that the package failed to reach the chain.
  Future<void> deliverRegtestExitCpfp({
    required String vtxoId,
    required String exitTxid,
    required String childTxid,
    required List<int> rawTransaction,
    required BigInt admittedFeeSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletDeliverRegtestExitCpfp(
        that: this,
        vtxoId: vtxoId,
        exitTxid: exitTxid,
        childTxid: childTxid,
        rawTransaction: rawTransaction,
        admittedFeeSats: admittedFeeSats,
      );

  /// Lists due first-attempt children without signing or broadcasting.
  Future<List<ScuttleExitCpfpStep>> dueRegtestExitCpfp({
    required List<String> vtxoIds,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletDueRegtestExitCpfp(
    that: this,
    vtxoIds: vtxoIds,
  );

  /// Estimates the selected exits at an optional exact integer sats/vB rate.
  Future<ScuttleExitFeeEstimate> estimateExit({
    required List<String> vtxoIds,
    BigInt? feeRateSatPerVb,
    String? destination,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletEstimateExit(
    that: this,
    vtxoIds: vtxoIds,
    feeRateSatPerVb: feeRateSatPerVb,
    destination: destination,
  );

  /// Returns persisted live and terminal exits. A missing VTXO fails the whole observation.
  Future<List<ScuttleExit>> exitInventory() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletExitInventory(that: this);

  /// Capture a local review; the host must bind and persist it with its own admission.
  Future<ScuttleExitProgressReview> exitProgressReview({
    required BigInt feeRateSatPerVb,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletExitProgressReview(
    that: this,
    feeRateSatPerVb: feeRateSatPerVb,
  );

  /// Finalizes an externally funded regtest board after confirmation.
  /// Scuttle scans all pending boards here; refuse any wallet with boards
  /// capable of broadcasting funding or approaching exit salvage.
  Future<String?> finalizeRegtestBoard({required String fundingTxid}) =>
      ScuttleCore.instance.api.crateApiWalletScuttleWalletFinalizeRegtestBoard(
        that: this,
        fundingTxid: fundingTxid,
      );

  Future<String> fingerprint() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletFingerprint(that: this);

  /// Imports confirmed change from the host's exact journaled child. This
  /// updates only the reserve graph and never runs the native wallet sync.
  Future<ScuttleReserveCoin?> importConfirmedRegtestCpfpChange({
    required String childTxid,
    required List<int> rawTransaction,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletImportConfirmedRegtestCpfpChange(
        that: this,
        childTxid: childTxid,
        rawTransaction: rawTransaction,
      );

  /// Imports only the initial, confirmed, host-journaled reserve funding.
  /// Repeated imports of the same funding are safe; no transaction is broadcast.
  Future<ScuttleReserveCoin?> importInitialRegtestReserveFunding({
    required String txid,
    required String destination,
    required BigInt amountSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletImportInitialRegtestReserveFunding(
        that: this,
        txid: txid,
        destination: destination,
        amountSats: amountSats,
      );

  /// Performs the native initial scan, which can also rebroadcast stored transactions.
  Future<void> initialScan() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletInitialScan(that: this);

  /// Derives and stores a fresh full Ark mailbox address.
  Future<String> newArkAddress() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletNewArkAddress(that: this);

  /// Reads the chain source tip and cached native inventory without synchronizing it.
  Future<ScuttleObservation> observation() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletObservation(that: this);

  /// Derives and persists a new Scuttle board key; requires server and chain access.
  Future<ScuttleBoardFunding> prepareBoard() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletPrepareBoard(that: this);

  /// Signs only selected claimable exit inputs. Does not broadcast or use reserve coins.
  Future<ScuttleExitClaim> prepareExitClaim({
    required List<String> vtxoIds,
    required String destination,
    required BigInt maxFeeSats,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletPrepareExitClaim(
    that: this,
    vtxoIds: vtxoIds,
    destination: destination,
    maxFeeSats: maxFeeSats,
  );

  /// Builds a non-replacement child for one reviewed regtest exit without
  /// broadcasting it. The host must durably admit the exact bytes and debit
  /// its cumulative exit budget before any later delivery.
  Future<ScuttleExitCpfpCandidate> prepareRegtestExitCpfp({
    required String vtxoId,
    required String exitTxid,
    required BigInt feeRateSatPerVb,
    required BigInt remainingFeeSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletPrepareRegtestExitCpfp(
        that: this,
        vtxoId: vtxoId,
        exitTxid: exitTxid,
        feeRateSatPerVb: feeRateSatPerVb,
        remainingFeeSats: remainingFeeSats,
      );

  /// Signing is separate from review. The caller must first admit the quote
  /// exclusively and must record the resulting bytes before delivering them.
  Future<ScuttleMixedClaim> prepareRegtestMixedClaim({
    required List<String> vtxoIds,
    required String destination,
    required List<String> reserveOutpoints,
    required BigInt feeRateSatPerVb,
    required BigInt expectedAmountSats,
    required BigInt expectedFeeSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletPrepareRegtestMixedClaim(
        that: this,
        vtxoIds: vtxoIds,
        destination: destination,
        reserveOutpoints: reserveOutpoints,
        feeRateSatPerVb: feeRateSatPerVb,
        expectedAmountSats: expectedAmountSats,
        expectedFeeSats: expectedFeeSats,
      );

  /// Compare the entire local review under admission, then progress at its exact rate.
  /// Scuttle may use any confirmed reserve UTXOs and provides no hard fee cap.
  /// An error after native admission must be treated as an unknown outcome.
  Future<List<ScuttleExitProgress>?> progressExits({
    required ScuttleExitProgressReview review,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletProgressExits(
    that: this,
    review: review,
  );

  /// Reports the recovery callback from this particular open.
  Future<ScuttleRecoveryStatus> recoveryStatus() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletRecoveryStatus(that: this);

  /// Advances exit states from chain observations, then returns the inventory.
  /// Never broadcasts, rebroadcasts, evicts or creates a CPFP: every
  /// transaction is delivered through the host's admission journal.
  Future<List<ScuttleExit>> refreshExitInventory() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletRefreshExitInventory(that: this);

  /// Admits only a wholly unsigned native-segwit PSBT. The host owns signing and broadcast.
  /// A failure after native admission must be treated as an unknown outcome, not retried.
  Future<ScuttleBoardResult> registerBoard({
    required String fundingToken,
    required List<int> unsignedPsbt,
  }) => ScuttleCore.instance.api.crateApiWalletScuttleWalletRegisterBoard(
    that: this,
    fundingToken: fundingToken,
    unsignedPsbt: unsignedPsbt,
  );

  /// Reveals and persists a new BIP86 address for the dedicated child reserve.
  Future<String> reserveAddress() => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletReserveAddress(that: this);

  /// Reviews a single sweep of all claimable exits and the entire reserve,
  /// without signing or broadcasting.
  Future<ScuttleMixedClaimReview> reviewRegtestMixedClaim({
    required List<String> vtxoIds,
    required String destination,
    required BigInt feeRateSatPerVb,
    required BigInt maxFeeSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletReviewRegtestMixedClaim(
        that: this,
        vtxoIds: vtxoIds,
        destination: destination,
        feeRateSatPerVb: feeRateSatPerVb,
        maxFeeSats: maxFeeSats,
      );

  /// A failure after native admission must be treated as an unknown outcome, not retried.
  Future<int> sendArk({required String address, required BigInt amountSats}) =>
      ScuttleCore.instance.api.crateApiWalletScuttleWalletSendArk(
        that: this,
        address: address,
        amountSats: amountSats,
      );

  /// Starts only the selected currently spendable VTXOs; an error after admission is unknown.
  Future<void> startExit({required List<String> vtxoIds}) => ScuttleCore
      .instance
      .api
      .crateApiWalletScuttleWalletStartExit(that: this, vtxoIds: vtxoIds);

  /// Verifies one host-journaled reserve funding transaction without running
  /// a wallet sync. This is not an import into BDK or spending authority.
  Future<ScuttleReserveCoin?> verifyRegtestReserveFunding({
    required String txid,
    required String destination,
    required BigInt amountSats,
  }) => ScuttleCore.instance.api
      .crateApiWalletScuttleWalletVerifyRegtestReserveFunding(
        that: this,
        txid: txid,
        destination: destination,
        amountSats: amountSats,
      );
}
